// Browser-safe Civora static site generator. Source: scripts/build.mjs.
// Keep parity via tests/studio.test.mjs. Do not edit this file independently.
const sections=[{"key":"us","label":"U.S.","heading":"The American Brief","dek":"Policy, institutions, and the decisions shaping everyday life.","tone":"america"},{"key":"world","label":"World","heading":"Beyond Borders","dek":"International developments, examined with care and context.","tone":"world"},{"key":"technology","label":"Technology","heading":"Technology & AI","dek":"Understanding the systems transforming how we live and work.","tone":"technology"},{"key":"business","label":"Business","heading":"The Business Desk","dek":"Markets, money, companies, and the forces behind the numbers.","tone":"business"},{"key":"science","label":"Science","heading":"Science & Discovery","dek":"Evidence, discoveries, and the methods behind the headlines.","tone":"science"},{"key":"culture","label":"Culture","heading":"Culture & Ideas","dek":"The stories, media, and creative work defining our moment.","tone":"culture"}];
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function slug(c){return c==="U.S."?"us":String(c).toLowerCase();}
function cap(s){return String(s).slice(0,1).toUpperCase()+String(s).slice(1);}
function label(a){return a.status==="sample"?"EDITORIAL SAMPLE":a.status==="published"?"REPORTING":"DRAFT";}
function rootOf(file){const n=file.split("/").length-1;return n?"../".repeat(n):"./";}
function categoryURL(a,root){return root+"section/"+slug(a.cat)+"/";}
function articleURL(a,root){return root+"article/"+encodeURIComponent(a.id)+"/";}
function picture(a,cls=""){return `<div class="editorial-art art--${esc(slug(a.cat))} ${cls}" aria-hidden="true"><span class="art-orbit"></span><span class="art-no">${esc(a.cat)}</span><span class="art-word">${esc(a.art)}</span><span class="art-mark">C<span>·</span></span></div>`;}
function card(a,root,size=""){return `<article class="story-card ${size}"><a class="story-image-link" href="${articleURL(a,root)}" aria-label="${esc(a.title)}">${picture(a)}</a><div class="story-text"><div class="story-overline"><a href="${categoryURL(a,root)}">${esc(a.cat)}</a><span class="separator"></span>${label(a)}</div><h3><a href="${articleURL(a,root)}">${esc(a.title)}</a></h3><p>${esc(a.summary)}</p><div class="story-byline">${esc(a.author||"Civora Editorial")}</div></div></article>`;}
function listCard(a,root,i){return `<article class="feed-item"><div class="feed-index">${String(i+1).padStart(2,"0")}</div><div><div class="story-overline"><a href="${categoryURL(a,root)}">${esc(a.cat)}</a><span class="separator"></span>${label(a)}</div><h3><a href="${articleURL(a,root)}">${esc(a.title)}</a></h3><p>${esc(a.summary)}</p></div><a class="feed-arrow" aria-label="Read ${esc(a.title)}" href="${articleURL(a,root)}">↗</a></article>`;}
function header(root,active){const nav=[{n:"Home",u:"",id:"home"},{n:"Discover",u:"discover/",id:"discover"},...sections.map(c=>({n:c.label,u:"section/"+c.key+"/",id:c.key})),{n:"Latest",u:"latest/",id:"latest"},{n:"Explainers",u:"explainers/",id:"explainers"},{n:"Opinion",u:"opinion/",id:"opinion"},{n:"Reviews",u:"reviews/",id:"reviews"},{n:"Fact Checks",u:"fact-checks/",id:"fact-checks"}];
return `<a class="skip-link" href="#main-content">Skip to content</a><div class="utility-bar"><div class="container utility-inner"><span><span class="live-dot"></span> INDEPENDENT DIGITAL JOURNALISM</span><span>FACTS FIRST · CONTEXT ALWAYS</span></div></div><header class="site-header"><div class="container masthead-inner"><div class="edition">CIVORA / THE DIGITAL EDITION<span>AN INDEPENDENT PUBLICATION</span></div><a class="wordmark" href="${root}" aria-label="Civora News home">CIVORA<span class="wordmark-rule"></span><em>NEWS</em></a><a class="header-search" href="${root}search/" aria-label="Search articles"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m16.5 16.5 5 5"></path></svg><span>Search</span></a></div><nav aria-label="Main navigation" class="nav-outer"><div class="container nav-scroll">${nav.map(n=>`<a ${active===n.id?'aria-current="page" class="nav-active"':''} href="${root+n.u}">${esc(n.n)}</a>`).join("")}</div></nav></header>`;}
function footer(root){return `<footer class="site-footer"><div class="container footer-grid"><div class="footer-brand"><a href="${root}" class="footer-wordmark">CIVORA <em>NEWS</em></a><p>A clearer perspective on an increasingly complicated world. Built around original insight, source transparency, and independent thinking.</p><span class="footer-small">© 2026 Civora News · Launch edition</span></div><div class="footer-links"><h3>Explore</h3><a href="${root}discover/">Reading Room</a><a href="${root}latest/">Latest</a><a href="${root}explainers/">Explainers</a><a href="${root}reviews/">Reviews</a><a href="${root}fact-checks/">Fact Checks</a></div><div class="footer-links"><h3>Publication</h3><a href="${root}about/">About</a><a href="${root}standards/">Editorial Standards</a><a href="${root}corrections/">Corrections</a><a href="${root}privacy/">Privacy</a></div><div class="footer-links"><h3>Connect</h3><a href="${root}newsletter/">Newsletter</a><a href="${root}advertise/">Advertise</a><a href="${root}contact/">Contact</a></div></div><div class="container footer-bottom"><span>INDEPENDENT BY DESIGN.</span><span>Sample content is clearly labeled and is not breaking news.</span></div></footer>`;}
function frame(file,title,description,active,content,opts={}){const root=rootOf(file);const safeTitle=esc(title),desc=esc(description),canonical="https://civoranews.org/"+(file==="index.html"?"":file.endsWith("index.html")?file.slice(0,-10):file);return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111d2b"><meta name="color-scheme" content="light dark"><script>(()=>{const r=document.documentElement;try{const s=localStorage.getItem("civora-theme");r.dataset.theme=s==="dark"||s==="light"?s:(matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light")}catch{r.dataset.theme="light"}})();</script><meta name="description" content="${desc}"><meta name="robots" content="${opts.noindex?"noindex,follow":"index,follow"}"><link rel="canonical" href="${esc(canonical)}"><meta property="og:url" content="${esc(canonical)}"><meta property="og:site_name" content="Civora News"><meta property="og:type" content="${opts.isArticle?"article":"website"}"><meta property="og:title" content="${safeTitle} | Civora News"><meta property="og:description" content="${desc}"><title>${safeTitle} | Civora News</title><link rel="icon" href="${root}assets/civora-mark.svg" type="image/svg+xml"><link rel="stylesheet" href="${root}assets/site.css"><link rel="stylesheet" href="${root}assets/reading-room.css">${opts.isDiscover?`<link rel="stylesheet" href="${root}assets/discover.css">`:""}<script src="${root}assets/site.js" defer></script><script src="${root}assets/reading.js" defer></script>${opts.isDiscover?`<script src="${root}assets/discover.js" defer></script>`:""}</head><body>${header(root,active)}<main id="main-content" class="main-content">${content}</main>${footer(root)}</body></html>`;}
function eyebrow(s){return `<div class="eyebrow"><span class="eyebrow-line"></span>${esc(s)}</div>`;}
function intro(kicker,title,dek,secondary=""){return `<div class="page-intro">${eyebrow(kicker)}<div class="page-intro-row"><h1>${esc(title)}</h1><p>${esc(dek)}</p></div>${secondary?`<div class="intro-note">${esc(secondary)}</div>`:""}</div>`;}
function empty(title,desc){return `<section class="empty-state"><div class="empty-symbol">C<span>·</span></div><h2>${esc(title)}</h2><p>${esc(desc)}</p></section>`;}
function flipCard(a,root,index){
 const u=articleURL(a,root),featured=index===0;
 return '<article class="flip-card '+(featured?'flip-card--lead':'')+'" data-flip-card><div class="flip-inner">'+
 '<a class="flip-face flip-front" href="'+u+'" data-flip-trigger aria-label="Preview '+esc(a.title)+'">'+picture(a,"flip-art")+
 '<span class="flip-cover-head"><span class="flip-pill">'+esc(a.cat)+'</span><span class="flip-number">'+String(index+1).padStart(2,"0")+' / '+(featured?'FEATURED':'CIVORA')+'</span></span>'+
 '<span class="flip-cover-foot"><span class="flip-cover-label">'+(featured?'THE COVER STORY':'FROM THE CIVORA DESK')+'</span><span class="flip-hint"><span class="flip-hint-desktop">HOVER FOR DETAILS</span><span class="flip-hint-mobile">TAP TO PREVIEW</span> ↗</span></span></a>'+
 '<div class="flip-face flip-back"><div class="flip-back-header"><span class="flip-pill">'+esc(a.cat)+'</span><span class="flip-number">'+label(a)+'</span></div>'+
 '<div class="flip-back-story"><span class="flip-kicker">'+(featured?'THE COVER STORY':'THE STORY IN CONTEXT')+'</span><h3>'+esc(a.title)+'</h3><p>'+esc(a.summary)+'</p></div>'+
 '<div class="flip-back-footer"><a class="flip-read" href="'+u+'">Read full article <span aria-hidden="true">↗</span></a><button class="flip-close" type="button" data-flip-close aria-label="Close preview of '+esc(a.title)+'">Back to cover ✕</button></div>'+
 '</div></div></article>';
}
function homeDesk(s,index){
 return '<a class="home-deck-card" href="./section/'+s.key+'/"><small>'+String(index+1).padStart(2,"0")+' / '+esc(s.label.toUpperCase())+'</small><strong>'+esc(s.heading)+'</strong><span>'+esc(s.dek)+'</span><b class="home-deck-arrow" aria-hidden="true">↗</b></a>';
}
const supportedStoryKinds=new Set(["news","explainer","opinion","review","fact-check"]);
const legacyExplainerIds=new Set(["understanding-policy","global-context","ai-literacy","inflation-basics","research-check","source-check","business-records"]);
function storyKind(a){return supportedStoryKinds.has(a.kind)?a.kind:a.id==="critical-reviews"?"review":legacyExplainerIds.has(a.id)?"explainer":"news";}
function generateSite(articles){const files={};
 const published=articles.map((a,i)=>({article:a,order:i})).filter(x=>x.article.status==="published").sort((a,b)=>(b.article.publishedAt||"").localeCompare(a.article.publishedAt||"")||b.order-a.order).map(x=>x.article);
 const visible=[...published,...articles.filter(a=>a.status==="sample")],featured=visible[0],root="./";
const latestCards=visible.slice(1,5);
const hasPublished=visible.some(a=>a.status==="published");
const sampleFiles=new Set(visible.filter(a=>a.status==="sample").map(a=>"article/"+a.id+"/index.html"));
const topLine=`<div class="topline container"><span class="topline-left">THE CIVORA EDITION <i></i> INDEPENDENT BY DESIGN</span><span>${hasPublished?"PUBLISHED STORIES — SAMPLES CLEARLY LABELED":"LAUNCH PREVIEW — DEMONSTRATION ARTICLES"}</span></div>`;
const primary=featured?`<div class="hero-grid"><article class="lead-story"><a href="${articleURL(featured,root)}" class="lead-image" aria-label="Read ${esc(featured.title)}">${picture(featured,"art-large")}<span class="image-flag">CIVORA / COVER STORY</span></a><div class="lead-copy"><div class="story-overline"><a href="${categoryURL(featured,root)}">${esc(featured.cat)}</a><span class="separator"></span>${label(featured)}</div><h2><a href="${articleURL(featured,root)}">${esc(featured.title)}</a></h2><p>${esc(featured.summary)}</p><a class="read-story" href="${articleURL(featured,root)}">Read the story <span>↗</span></a></div></article><aside class="lead-side"><div class="section-minihead"><span>IN THE SPOTLIGHT</span><span>01 — 04</span></div>${latestCards.map((a,i)=>`<div class="side-headline"><span class="story-number">0${i+1}</span><div><a class="side-cat" href="${categoryURL(a,root)}">${esc(a.cat)}</a><h3><a href="${articleURL(a,root)}">${esc(a.title)}</a></h3></div></div>`).join("")}<div class="side-note"><strong>Note from the newsroom</strong><p>Civora is in its launch phase. These are demonstration explainers—not reported current events.</p><a href="./standards/">Our editorial standards ↗</a></div></aside></div>`:empty("Newsroom setup underway","Articles are being prepared for publication.");
const picked=visible.slice(1,7);
const homeContent=topLine+'<div class="container">'+
 intro("THE CIVORA COLLECTION","Stories worth turning over.","A card-first look at our journalism. Hover to reveal a headline and description, or tap to preview on your phone.",hasPublished?"Published reporting and editorial samples are labeled separately.":"Launch edition: sample explainers, not verified breaking-news reports.")+
 '<section class="flip-collection" aria-label="Article cover cards"><div class="section-heading"><div><span class="section-index">01 / THE STORY COLLECTION</span><h2>Explore the edition</h2></div><a href="./latest/" class="text-link">All stories ↗</a></div>'+
 '<div class="flip-guide"><span class="flip-guide-desktop">Move your cursor over a cover to discover its headline.</span><span class="flip-guide-touch">Tap a cover to preview, then select Read full article.</span><span>Every article has its own page.</span></div>'+
 '<div class="flip-grid">'+visible.map((a,i)=>flipCard(a,root,i)).join("")+'</div></section>'+
 '<section class="reading-room-teaser" aria-label="Explore the Reading Room"><div><span class="section-index">A NEW WAY TO READ CIVORA</span><h2>Follow a little curiosity.</h2><p>Not sure what to read next? Shuffle the stories, build a reading list, or try a quick challenge that sharpens your news instincts.</p></div><div class="reading-room-actions"><a href="./discover/" class="teaser-primary">Enter the Reading Room ↗</a><a href="./discover/" data-surprise>Surprise me ↗</a></div></section>'+
 '<section class="section-block"><div class="section-heading"><div><span class="section-index">02 / YOUR INTERESTS</span><h2>Explore by desk</h2></div><a href="./search/" class="text-link">Search Civora ↗</a></div>'+
 '<div class="home-deck-grid">'+sections.map((s,i)=>homeDesk(s,i)).join("")+'</div></section>'+
 '<div class="home-editorial-banner"><div><span class="section-index">03 / EDITORIAL INDEPENDENCE</span><h2>Context before clicks.</h2><p>We separate sources from opinion, make corrections visible, and disclose demonstrations clearly.</p></div><a class="button-light" href="./standards/">Editorial standards ↗</a></div>'+
 '<div class="sponsor-box"><span>ADVERTISEMENT</span><p>Reserved for future sponsors. No active paid endorsements.</p><a href="./advertise/">Advertising principles ↗</a></div></div>';
files["index.html"]=frame("index.html","Independent news, clearly explained","Civora News — independent digital journalism, insightful explainers and transparent sourcing.","home",homeContent);

const discoverItem=(a,i)=>{
 const link=articleURL(a,"../"),kind=label(a);
 return '<article class="discover-item" data-discover-item data-story-id="'+esc(a.id)+'" data-category="'+esc(a.cat)+'" data-title="'+esc(a.title)+'" data-summary="'+esc(a.summary)+'">'+
 '<div class="discover-item-meta"><span>'+esc(a.cat)+'</span><span>'+kind+'</span></div>'+
 '<h3>'+esc(a.title)+'</h3><p>'+esc(a.summary)+'</p>'+
 '<div class="discover-item-actions"><a href="'+link+'">Read story ↗</a><button class="requires-js" type="button" data-save-story="'+esc(a.id)+'" data-story-title="'+esc(a.title)+'" aria-pressed="false">＋ Save for later</button></div></article>';
};
const discoveryLead=visible[0];
const discoverBody='<div class="container discover-shell">'+
 intro("THE CIVORA READING ROOM","Follow your curiosity.","Browse a subject, find a surprising story, save something for later, or take a small challenge in thinking critically about news.","Your reading list and recent articles stay in this browser. No account or tracking required.")+
 '<div class="discover-hero"><section class="discover-feature" aria-label="Story shuffle"><span class="discover-feature-kicker">01 / STORY ROULETTE — EVERY STORY HAS A START</span>'+
 (discoveryLead?'<div><span id="pick-category" class="discover-pick-category">'+esc(discoveryLead.cat)+'</span><h2 id="pick-title" aria-live="polite">'+esc(discoveryLead.title)+'</h2><p id="pick-summary">'+esc(discoveryLead.summary)+'</p></div>'+
 '<div class="discover-feature-actions"><a class="discover-action" id="pick-link" href="'+articleURL(discoveryLead,"../")+'">Read this story ↗</a><a class="discover-ghost" href="'+articleURL(discoveryLead,"../")+'" data-discover-shuffle>Shuffle again ↻</a><button class="discover-ghost requires-js" id="pick-save" type="button" data-save-story="'+esc(discoveryLead.id)+'" data-story-title="'+esc(discoveryLead.title)+'" aria-pressed="false">＋ Save for later</button></div>':empty("The archive is getting ready","Come back when our first articles are published."))+
 '</section><aside class="discover-side"><div><span class="discover-note-label">A NOTE FROM THE DESK</span><h3>Good questions lead to better stories.</h3><p>Curiosity is the whole point. These are articles, not social-media posts: explore the context, question the evidence, and decide what matters to you.</p></div><div class="discover-micro"><span>∞</span><span>NO TRACKING. NO ENDLESS FEED. YOUR CHOICE.</span></div><a class="discover-side-link" href="../standards/">How Civora checks its reporting <span aria-hidden="true">↗</span></a></aside></div>'+
 '<section class="discover-section" aria-label="Browse Civora topics"><div class="section-heading"><div><span class="section-index">02 / FIND YOUR NEXT STORY</span><h2>Pick a direction</h2></div><a class="text-link" href="../latest/">The full archive ↗</a></div><p class="discover-section-intro">Choose a topic to narrow the collection. Every card links to a real article page, including those marked as editorial demonstrations.</p>'+
 '<div class="topic-filters" role="group" aria-label="Filter stories by topic"><button class="topic-chip requires-js" type="button" data-topic-filter="all" aria-pressed="true">All stories</button>'+
 sections.map(sec=>'<button class="topic-chip requires-js" type="button" data-topic-filter="'+esc(sec.label)+'" aria-pressed="false">'+esc(sec.label)+'</button>').join("")+
 '</div><p id="discover-count" class="discover-count" role="status">'+visible.length+' stories to explore</p><div class="discover-grid">'+visible.map((a,i)=>discoverItem(a,i)).join("")+'</div></section>'+
 '<div class="discover-pair"><section class="discover-shelf" aria-label="Saved reading list"><div class="discover-shelf-top"><h2>Your reading list</h2><small><span id="saved-total">0</span> SAVED</small></div><p>Keep interesting stories here. They stay on this device and never require an account.</p><ul id="saved-stories" class="discover-shelf-list"></ul><p id="saved-empty" class="discover-empty">Nothing saved yet. Try the save button on an article.</p></section>'+
 '<section class="discover-shelf" aria-label="Recently opened articles"><div class="discover-shelf-top"><h2>Recently opened</h2><small><span id="recent-total">0</span> READ</small></div><p>Pick up an article you visited recently. This history is local to your browser.</p><ul id="recent-stories" class="discover-shelf-list"></ul><p id="recent-empty" class="discover-empty">Your recently opened stories will appear here.</p></section></div>'+
 '<section class="discover-quiz" aria-label="News-literacy challenge"><div class="discover-quiz-lead"><span class="section-index">03 / THE CRITICAL READER CHALLENGE</span><h2>Can you spot the stronger evidence?</h2><p>Five original questions about headlines, surveys, sources, and sponsorships. No scoreboards, just sharper reading instincts.</p></div><div id="quiz-stage" class="quiz-panel" aria-live="polite"><p class="discover-quiz-noscript">This optional interactive challenge runs in your browser. You can still read our <a href="../standards/">editorial standards</a> without JavaScript.</p></div></section>'+
 '</div>';
files["discover/index.html"]=frame("discover/index.html","Discover stories in the Reading Room","Explore Civora stories, keep a private reading list, and practice evaluating news evidence.","discover",discoverBody,{isDiscover:true});

for(const s of sections){const list=visible.filter(a=>slug(a.cat)===s.key);
const lead=list[0];const related=visible.filter(a=>slug(a.cat)!==s.key).slice(0,3);
const body=`<div class="container">${intro("SECTION / "+s.label.toUpperCase(),s.heading,s.dek,hasPublished?"Published stories and editorial samples are identified individually.":"Articles in this preview are educational samples, not live news coverage.")}<div class="section-heading"><div><span class="section-index">THE ${esc(s.label.toUpperCase())} DESK</span><h2>Featured stories</h2></div><span class="muted">${list.length} ${list.length===1?"STORY":"STORIES"}</span></div>${lead?`<div class="category-lead"><a href="${articleURL(lead,"../../")}" class="category-image">${picture(lead,"art-large")}</a><div class="category-copy">${eyebrow(label(lead))}<h2><a href="${articleURL(lead,"../../")}">${esc(lead.title)}</a></h2><p>${esc(lead.summary)}</p><a class="text-link" href="${articleURL(lead,"../../")}">Read story ↗</a></div></div>${list.length>1?`<div class="card-grid">${list.slice(1).map(a=>card(a,"../../")).join("")}</div>`:""}`:empty("Coverage is taking shape","New articles will appear here after editorial review.")}<section class="section-block"><div class="section-heading"><div><span class="section-index">ACROSS CIVORA</span><h2>More to explore</h2></div></div><div class="card-grid">${related.map(a=>card(a,"../../")).join("")}</div></section></div>`;
files["section/"+s.key+"/index.html"]=frame("section/"+s.key+"/index.html",s.label+" News",s.dek,s.key,body);}
const listing=(path,title,dek,filter,notes="")=>{const list=visible.filter(filter);const rt=rootOf(path);
const content=`<div class="container">${intro("CIVORA / "+title.toUpperCase(),title,dek,notes)}${list.length?`<div class="feed-layout"><div class="feed-main"><div class="section-heading"><div><span class="section-index">THE ARCHIVE</span><h2>${esc(list.length+" "+(list.length===1?"story":"stories"))}</h2></div></div>${list.map((a,i)=>listCard(a,rt,i)).join("")}</div><aside class="feed-aside"><div class="about-panel">${eyebrow("ABOUT THIS SECTION")}<h3>Clarity is our standard.</h3><p>Every demo article is explicitly labeled. Real news must be independently verified and clearly sourced before publication.</p><a class="text-link" href="${rt}standards/">See our standards ↗</a></div></aside></div>`:empty("This desk is taking shape","We haven't published verified coverage in this section yet. We won't invent stories to fill space.")}</div>`;
files[path]=frame(path,title,dek,title==="Latest"?"latest":title==="Explainers"?"explainers":title==="Opinion"?"opinion":title==="Fact Checks"?"fact-checks":"reviews",content);};
listing("latest/index.html","Latest","Browse Civora reporting and clearly marked editorial demonstrations.",()=>true,hasPublished?"Published stories and samples are identified individually.":"Launch preview: current articles are samples, not real-time news.");
listing("explainers/index.html","Explainers","Go beyond the headline with accessible background and useful detail.",a=>storyKind(a)==="explainer");
listing("opinion/index.html","Opinion","Distinct perspectives, explicitly separated from factual news reporting.",a=>storyKind(a)==="opinion","Commentary is labeled as opinion, not straight news reporting.");
listing("reviews/index.html","Reviews","Independent criticism, considered analysis, and original perspectives on creative work.",a=>storyKind(a)==="review");
const simplePage=(path,kicker,title,lead,body,active)=>{files[path]=frame(path,title,lead,active,`<div class="container legal-layout">${intro(kicker,title,lead)}<div class="prose">${body}</div></div>`)};
listing("fact-checks/index.html","Fact Checks","Evidence-based assessments of public claims, with primary sources and clear conclusions.",a=>storyKind(a)==="fact-check","We distinguish established evidence from what remains unresolved.");
simplePage("newsletter/index.html","THE CIVORA DIGEST","The Newsletter","A deliberate weekly selection of the stories worth your attention.",`<div class="newsletter-panel"><span class="newsletter-big">THE WEEK, IN CONTEXT.</span><h2>Coming soon.</h2><p>Our email newsletter hasn't launched. We're not collecting addresses or pretending to have an active mailing list. When it does launch, subscriptions will be opt-in and clearly described.</p></div><h2>What we're planning</h2><p>A short editorial note, important explainers, links to primary evidence, and a thoughtful reading list—with no fake urgency or clickbait.</p>`,"newsletter");
simplePage("about/index.html","OUR PUBLICATION","About Civora","Independent by design. Interested in substance over noise.",`<h2>What Civora is</h2><p>Civora News is an independent digital publication under development. We aim to cover U.S. affairs, world events, technology, business, science and culture with thoughtful context and transparent sourcing.</p><p>Demonstration explainers are clearly marked and separated from independently verified published reporting. Civora does not claim interviews or reporting that did not occur.</p><h2>Our commitments</h2><p>Accuracy before speed. Clear separation of news, opinion and advertising. Honest corrections. Respect for source material and original reporting. No invented quotes or staged reporting presented as fact.</p><h2>Who runs it?</h2><p>The publication is currently an independent project. A public masthead and newsroom contact will be added as appropriate before commissioning outside reporting.</p>`,"about");
simplePage("standards/index.html","HOW WE WORK","Editorial Standards","The audience deserves verifiable information, clear attribution and visible corrections.",`<h2>Verification</h2><p>Every factual claim should be traceable to reliable evidence. Primary sources are preferred where appropriate. For disputed claims, review independently sourced evidence and represent meaningful uncertainty.</p><h2>Editorial independence</h2><p>Advertisers do not direct reporting. Sponsored material must be conspicuously labeled, distinct from newsroom articles, and disclosed wherever it appears.</p><h2>Accuracy and corrections</h2><p>Dates, names, figures, quotations, headlines and context should be checked before publication. Material errors are corrected promptly with an appropriate dated note.</p><h2>AI use</h2><p>Software may assist with organization and proofreading but cannot independently confirm facts. We will not invent reporting, sources, quotes or interviews and present them as real.</p><h2>Copyright and imagery</h2><p>Use original, public-domain or appropriately licensed media. Attribution does not automatically grant permission to reuse copyrighted images or articles.</p>`,"standards");
simplePage("corrections/index.html","ACCOUNTABILITY","Corrections","Our responsibility continues after an article is published.",`<h2>When an article is wrong</h2><p>We review the underlying evidence, correct verified errors and disclose significant corrections with a date and explanation. Corrections should not quietly erase meaningful mistakes from the record.</p><h2>Corrections log</h2><p>Significant corrections to published reporting will be logged here with dates and explanations. Editorial demonstrations do not establish a reporting track record.</p><p>Readers will be able to submit corrections once the official newsroom contact address is configured.</p>`,"corrections");
simplePage("privacy/index.html","TRANSPARENCY","Privacy","A minimal first version without third-party advertising trackers or newsletter signup forms.",`<h2>What this site collects</h2><p>The public newspaper does not use reader accounts or a newsletter subscription database. Search filters the article archive in your browser; submitting a search may place the query in the page URL. Theme preferences, optional saved stories, and recently opened article identifiers may be stored in your browser’s local storage. You can clear them through browser site-data controls. These reading features do not upload your reading history to Civora.</p><h2>Hosting and outside links</h2><p>GitHub Pages and internet intermediaries may handle routine technical request data. External links are operated by their respective websites and follow their own privacy practices.</p><h2>Future changes</h2><p>Authorized newsroom editors use a separate Studio interface. Until dedicated staff sign-in is enabled, that tool uses GitHub credentials supplied by the editor, and unsent drafts stay in that browser’s local storage. This is not a public reader registration system. Any future analytics, advertising or subscriptions require an updated disclosure.</p>`,"privacy");
simplePage("advertise/index.html","PARTNER WITH CIVORA","Advertising","Future partnerships, clearly identified and independent of editorial decisions.",`<div class="policy-callout"><strong>Advertising sales are not yet open.</strong><p>Our launch preview has no paid sponsors, no guaranteed reach figures and no active sponsorship placements.</p></div><h2>Our principles</h2><p>Future ads will be clearly labeled and visually distinguishable from reporting. No advertiser can purchase a favorable news article or influence fact-checking conclusions.</p><p>A media kit with verified readership statistics and an official business contact will be prepared before accepting sponsors.</p>`,"advertise");
simplePage("contact/index.html","GET IN TOUCH","Contact","Newsroom contact details will be announced when an official mailbox is configured.",`<h2>For now</h2><p>There is no public newsroom inbox or anonymous tip system. Please do not send confidential sources, sensitive details or personal data through public GitHub issues.</p><h2>Corrections and feedback</h2><p>An official contact method and privacy-aware corrections process will be introduced before expanding reporting operations.</p>`,"contact");
const searchR="../";
const searchBody=`<div class="container">${intro("EXPLORE THE ARCHIVE","Search Civora","Find articles and clearly labeled editorial samples by headline, category, or topic.","All stories are visible below even when JavaScript is disabled.")}<form role="search" class="search-form" action="./" method="get"><label for="site-search">Search stories</label><div class="search-controls"><input type="search" id="site-search" name="q" placeholder="Try “technology”, “policy”, or “science”" autocomplete="off"><button type="submit">Search <span>↗</span></button></div></form><div id="search-status" role="status" aria-live="polite" class="search-status">${visible.length} stories in the archive</div><div class="search-list" id="search-results">${visible.map((a,i)=>`<div class="search-entry" data-search="${esc((a.title+" "+a.summary+" "+a.cat).toLowerCase())}">${listCard(a,searchR,i)}</div>`).join("")}</div><div class="empty-search" id="search-empty" hidden>No matching stories. Try a different term.</div></div>`;
files["search/index.html"]=frame("search/index.html","Search","Search the Civora News article archive.","search",searchBody,{noindex:true});
for(const a of visible){const file=`article/${a.id}/index.html`,r=rootOf(file),isSample=a.status==="sample";const srcs=(a.sources||[]).map(x=>{const i=x.indexOf(": https://");const name=i>-1?x.slice(0,i):x;const url=i>-1?x.slice(i+2):"";return url.startsWith("https://")?`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} <span aria-hidden="true">↗</span></a></li>`:"";}).join("");
const related=visible.filter(x=>x.id!==a.id).sort((x,y)=>Number(y.cat===a.cat)-Number(x.cat===a.cat)).slice(0,3);
const relatedMarkup=related.length?'<section class="reading-continue"><div class="section-heading"><div><span class="section-index">MORE IN THE EDITION</span><h2>Keep exploring</h2></div><a class="text-link" href="'+r+'discover/">Discover more ↗</a></div><div class="reading-next-grid">'+related.map(x=>'<a class="reading-next-card" href="'+articleURL(x,r)+'"><small>'+esc(x.cat)+' / '+label(x)+'</small><strong>'+esc(x.title)+'</strong><span>Read the story ↗</span></a>').join("")+'</div></section>':'';
const content=`<div class="container article-frame" data-story-id="${esc(a.id)}"><div class="article-crumb"><a href="${r}">Home</a><span> / </span><a href="${categoryURL(a,r)}">${esc(a.cat)}</a><span> / Article</span></div><article><header class="article-header">${eyebrow(a.cat+" / "+label(a))}<h1>${esc(a.title)}</h1><p class="article-dek">${esc(a.summary)}</p><div class="article-meta"><span>BY <strong>${esc(a.author||"Civora Editorial")}</strong></span><span>${isSample?"DEMONSTRATION CONTENT":a.publishedAt?`PUBLISHED ${esc(a.publishedAt)}`:"EDITORIAL"}</span></div></header>${picture(a,"article-hero")}${isSample?'<div class="sample-disclosure"><strong>Editorial sample.</strong> This article demonstrates Civora’s publishing layout. It is not a freshly reported news story or evidence of a recent event.</div>':""}<div class="article-columns"><div class="article-body">${a.body.map(p=>`<p>${esc(p)}</p>`).join("")}<section class="article-sources"><h2>Sources & further reading</h2>${srcs?`<ul>${srcs}</ul>`:"<p>This article does not currently list external sources.</p>"}<p class="source-caption">Reference links are provided for reader research; their inclusion does not imply endorsement.</p></section></div><aside class="article-rail"><span class="rail-title">THE CIVORA PRINCIPLE</span><p>Journalism should help you understand what we know, how we know it, and what remains uncertain.</p><a href="${r}standards/">Our editorial standards ↗</a></aside></div></article><div class="article-bottom"><a class="button-light dark-button" href="${r}latest/">← Return to all stories</a><a class="text-link" href="${categoryURL(a,r)}">More in ${esc(a.cat)} ↗</a></div>${relatedMarkup}</div>`;
files[file]=frame(file,a.title,a.summary,slug(a.cat),content,{isArticle:true,noindex:isSample});}
const sitemapPaths=Object.keys(files).filter(x=>x.endsWith(".html")&&!x.startsWith("editor/")&&x!=="search/index.html"&&!sampleFiles.has(x));const domain="https://civoranews.org/"; files["sitemap.xml"]=`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemapPaths.map(p=>`<url><loc>${domain+(p==="index.html"?"":p.replace(/index\.html$/,""))}</loc></url>`).join("")}</urlset>`;
files["robots.txt"]="User-agent: *\nAllow: /\nSitemap: "+domain+"sitemap.xml\n";
files[".nojekyll"]="";
return files;
}

export {generateSite};
